=== FILE: tb/tb_mac8.v ===
// Self-checking scoreboard testbench for mac8.
// Reference model written from interface_spec.md (MAC-RESET, MAC-CLEAR,
// MAC-ACC, MAC-HOLD, MAC-SAT, MAC-STICKY), not from the RTL.
// Inputs are driven on the falling edge; the model steps at the rising edge;
// acc and sat are compared 1 ns after every rising edge.
`timescale 1ns / 1ps
module tb_mac8;
    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg        rst_n = 1'b0;
    reg        clr   = 1'b0;
    reg        en    = 1'b0;
    reg  [7:0] a     = 8'd0;
    reg  [7:0] b     = 8'd0;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk(clk), .rst_n(rst_n), .clr(clr), .en(en),
        .a(a), .b(b), .acc(acc), .sat(sat)
    );

    // ---------------- reference model state ----------------
    reg [31:0] m_acc;
    reg        m_sat;
    reg        m_valid;

    integer n_pass;
    integer n_fail;
    integer cyc;
    integer i;
    integer k;

    // corner counters
    integer c_rst_en;      // reset with an accumulate offered
    integer c_rst_clr;     // reset and clear together
    integer c_clr_en;      // clear with an accumulate offered
    integer c_hold;        // en low, clr low, out of reset
    integer c_unsigned;    // accumulate with an operand >= 0x80
    integer c_exact_max;   // sum lands exactly on 0xFFFFFF, no saturation
    integer c_sat_event;   // first saturation since clear/reset
    integer c_resat;       // saturating accumulate while already saturated
    integer c_sticky_hold; // hold while saturated
    integer c_sticky_acc;  // non-saturating accumulate while saturated
    integer c_rst_sat;     // reset while saturated
    integer c_clr_sat;     // clear while saturated

    reg [31:0] rng_c;
    reg [31:0] rng_d;
    reg        r_r, r_c, r_e;
    reg [7:0]  r_a, r_b;

    reg [8*128-1:0] nonce_str;
    reg [7:0]       ch;
    reg             got_nonce;

    function [31:0] xs32;
        input [31:0] x;
        reg   [31:0] y;
        begin
            y = x ^ (x << 13);
            y = y ^ (y >> 17);
            y = y ^ (y << 5);
            xs32 = y;
        end
    endfunction

    // One rising edge of the specified behaviour.
    task model_step;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        reg   [31:0] p;
        reg   [31:0] s;
        begin
            p = {24'd0, ia} * {24'd0, ib};
            if (r == 1'b0) begin
                // MAC-RESET
                if (e)      c_rst_en  = c_rst_en + 1;
                if (c)      c_rst_clr = c_rst_clr + 1;
                if (m_valid && m_sat) c_rst_sat = c_rst_sat + 1;
                m_acc   = 32'd0;
                m_sat   = 1'b0;
                m_valid = 1'b1;
            end else if (!m_valid) begin
                // model state unknown before the first reset: nothing to predict
                m_valid = 1'b0;
            end else if (c) begin
                // MAC-CLEAR: clear wins over accumulate
                if (e)     c_clr_en  = c_clr_en + 1;
                if (m_sat) c_clr_sat = c_clr_sat + 1;
                m_acc = 32'd0;
                m_sat = 1'b0;
            end else if (e) begin
                // MAC-ACC, MAC-SAT
                if (ia[7] || ib[7]) c_unsigned = c_unsigned + 1;
                s = m_acc + p;
                if (s > 32'h00FFFFFF) begin
                    if (m_sat) c_resat = c_resat + 1;
                    else       c_sat_event = c_sat_event + 1;
                    m_acc = 32'h00FFFFFF;
                    m_sat = 1'b1;
                end else begin
                    if (m_sat) c_sticky_acc = c_sticky_acc + 1;
                    if (s == 32'h00FFFFFF && !m_sat) c_exact_max = c_exact_max + 1;
                    m_acc = s;
                    // MAC-STICKY: m_sat unchanged
                end
            end else begin
                // MAC-HOLD
                c_hold = c_hold + 1;
                if (m_sat) c_sticky_hold = c_sticky_hold + 1;
            end
        end
    endtask

    // Drive one cycle, step the model, compare every output.
    task step;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            @(negedge clk);
            rst_n = r; clr = c; en = e; a = ia; b = ib;
            @(posedge clk);
            model_step(r, c, e, ia, ib);
            #1;
            cyc = cyc + 1;
            if (m_valid) begin
                if ((acc !== m_acc[23:0]) || (sat !== m_sat)) begin
                    n_fail = n_fail + 1;
                    if (n_fail <= 10)
                        $display("MISMATCH cycle %0d: rst_n=%b clr=%b en=%b a=%h b=%h | expected acc=%h sat=%b | got acc=%h sat=%b",
                                 cyc, r, c, e, ia, ib, m_acc[23:0], m_sat, acc, sat);
                end else begin
                    n_pass = n_pass + 1;
                end
            end
        end
    endtask

    task corner;
        input integer count;
        input [8*40-1:0] name;
        begin
            if (count > 0) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                $display("CORNER NOT REACHED: %0s", name);
            end
        end
    endtask

    initial begin
        n_pass = 0; n_fail = 0; cyc = 0;
        m_acc = 32'd0; m_sat = 1'b0; m_valid = 1'b0;
        c_rst_en = 0; c_rst_clr = 0; c_clr_en = 0; c_hold = 0; c_unsigned = 0;
        c_exact_max = 0; c_sat_event = 0; c_resat = 0; c_sticky_hold = 0;
        c_sticky_acc = 0; c_rst_sat = 0; c_clr_sat = 0;
        rng_c = 32'h1234ABCD;
        rng_d = 32'h0BADF00D;
        nonce_str = 0;
        got_nonce = 1'b0;

        // S1: reset with an accumulate offered; reset together with clear
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);

        // S2: accumulate, operands unsigned
        step(1'b1, 1'b0, 1'b1, 8'h03, 8'h05);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h01);
        step(1'b1, 1'b0, 1'b1, 8'h80, 8'h80);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h7F, 8'h81);

        // S3: hold with operands present
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'h12, 8'h34);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);

        // S4: clear wins over accumulate; clear without en
        step(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h02, 8'h02);
        step(1'b1, 1'b1, 1'b0, 8'h12, 8'h34);

        // S5: exact boundary. 258*255*255 + 255*3 = 0xFFFFFF, no saturation
        for (i = 0; i < 258; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h03);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);
        // one more unit saturates
        step(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);

        // S6: sticky flag through hold, zero-product accumulate, re-saturation
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);
        step(1'b1, 1'b0, 1'b0, 8'hAA, 8'h55);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);
        step(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);

        // S7: clear from saturated, accumulation restarts from 0
        step(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h02, 8'h03);
        step(1'b1, 1'b0, 1'b0, 8'h02, 8'h03);

        // S8: saturate again, then reset in the middle of operation
        for (i = 0; i < 260; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);
        step(1'b1, 1'b0, 1'b1, 8'h10, 8'h10);

        // S9: saturate, then clear with accumulate offered while saturated
        for (i = 0; i < 260; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);

        // S10: seeded random traffic, checked every cycle
        for (i = 0; i < 6000; i = i + 1) begin
            rng_c = xs32(rng_c);
            rng_d = xs32(rng_d);
            r_r = (rng_c[10:0]  != 11'd0);
            r_c = (rng_c[21:11] == 11'd0);
            r_e = (rng_c[23:22] != 2'd0);
            case (rng_c[25:24])
                2'd0: begin r_a = rng_d[7:0];          r_b = rng_d[15:8];          end
                2'd1: begin r_a = rng_d[7:0] | 8'hC0;  r_b = rng_d[15:8] | 8'hC0;  end
                2'd2: begin r_a = rng_d[7:0] & 8'h0F;  r_b = rng_d[15:8] & 8'h0F;  end
                default: begin r_a = rng_d[16] ? 8'h00 : rng_d[7:0];
                               r_b = rng_d[16] ? rng_d[15:8] : 8'h00; end
            endcase
            step(r_r, r_c, r_e, r_a, r_b);
        end

        // Corners the run must have reached
        corner(c_rst_en,      "reset with accumulate offered");
        corner(c_rst_clr,     "reset with clear");
        corner(c_clr_en,      "clear with accumulate offered");
        corner(c_hold,        "hold");
        corner(c_unsigned,    "operand >= 0x80");
        corner(c_exact_max,   "sum exactly 0xFFFFFF");
        corner(c_sat_event,   "saturation");
        corner(c_resat,       "saturation while saturated");
        corner(c_sticky_hold, "hold while saturated");
        corner(c_sticky_acc,  "zero-product accumulate while saturated");
        corner(c_rst_sat,     "reset while saturated");
        corner(c_clr_sat,     "clear while saturated");

        if (n_pass == 0) begin
            n_fail = n_fail + 1;
            $display("ERROR: no comparison was made");
        end

        $display("tb_mac8: %0d cycles, saturations=%0d exact_max=%0d sticky_hold=%0d sticky_acc=%0d",
                 cyc, c_sat_event, c_exact_max, c_sticky_hold, c_sticky_acc);

        if ($value$plusargs("NIRMAAN_NONCE=%s", nonce_str))      got_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce_str)) got_nonce = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce_str))         got_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce_str))         got_nonce = 1'b1;
        if (!got_nonce) begin
            n_fail = n_fail + 1;
            $display("ERROR: no nonce plusarg found");
        end

        $write("NIRMAAN-SIM ");
        for (k = 127; k >= 0; k = k - 1) begin
            ch = nonce_str[k*8 +: 8];
            if (ch != 8'd0) $write("%c", ch);
        end
        $display(" %0d passed, %0d failed", n_pass, n_fail);
        $finish;
    end
endmodule
=== END FILE ===
